1	export type Cell = [number, number];
2	
3	const keyOf = ([x, y]: Cell): string => `${x},${y}`;
4	
5	const neighborsOf = ([x, y]: Cell): Cell[] => [
6	  [x - 1, y - 1],
7	  [x, y - 1],
8	  [x + 1, y - 1],
9	  [x - 1, y],
10	  [x + 1, y],
11	  [x - 1, y + 1],
12	  [x, y + 1],
13	  [x + 1, y + 1],
14	];
15	
16	// Rule 1: a live cell with fewer than two live neighbors dies.
17	const diesOfUnderpopulation = (liveNeighbors: number): boolean =>
18	  liveNeighbors < 2;
19	
20	// Rule 3: a live cell with more than three live neighbors dies.
21	const diesOfOverpopulation = (liveNeighbors: number): boolean =>
22	  liveNeighbors > 3;
23	
24	// Rule 2: a live cell with two or three live neighbors lives on.
25	const survives = (liveNeighbors: number): boolean =>
26	  !diesOfUnderpopulation(liveNeighbors) &&
27	  !diesOfOverpopulation(liveNeighbors);
28	
29	// Rule 4: a dead cell with exactly three live neighbors becomes alive.
30	const isBorn = (liveNeighbors: number): boolean => liveNeighbors === 3;
31	
32	// Only a live cell or a neighbor of one can be alive next generation;
33	// every other cell has no live neighbors and stays dead.
34	const candidatesFrom = (liveCells: Cell[]): Cell[] =>
35	  deduplicate(liveCells.flatMap((cell) => [cell, ...neighborsOf(cell)]));
36	
37	const deduplicate = (cells: Cell[]): Cell[] => [
38	  ...new Map(cells.map((cell) => [keyOf(cell), cell])).values(),
39	];
40	
41	export function nextGeneration(liveCells: Cell[]): Cell[] {
42	  const living = new Set(liveCells.map(keyOf));
43	  const isAlive = (cell: Cell): boolean => living.has(keyOf(cell));
44	
45	  const liveNeighborCount = (cell: Cell): number =>
46	    neighborsOf(cell).filter(isAlive).length;
47	
48	  const livesOn = (cell: Cell): boolean => {
49	    const liveNeighbors = liveNeighborCount(cell);
50	    return isAlive(cell) ? survives(liveNeighbors) : isBorn(liveNeighbors);
51	  };
52	
53	  return candidatesFrom(liveCells).filter(livesOn);
54	}
